css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; left: 50%; top: 50%; width: calc(var(--loader-size) * .4); height: calc(var(--loader-size) * .4); margin: calc(var(--loader-size) * -.2) 0 0 calc(var(--loader-size) * -.2); border: calc(var(--loader-size) * .06) solid var(--accent); border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--accent-2) 18%, transparent), transparent 70%); animation: search calc(var(--loader-speed) * 3) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; right: calc(var(--loader-size) * -.13); bottom: calc(var(--loader-size) * -.07); width: calc(var(--loader-size) * .2); height: calc(var(--loader-size) * .07); border-radius: 4px; background: var(--accent); transform: rotate(45deg); transform-origin: left center; }
@keyframes search { 0%, 100% { transform: translate(-42%, -40%); } 25% { transform: translate(12%, -32%); } 50% { transform: translate(22%, 20%); } 75% { transform: translate(-30%, 12%); } }
